const wireWords={sortSettings:'調整排序',cutRecords:'裁線紀錄',modifiedBy:'修改人員',exportTooLarge:'照片超過單次匯出容量，請分線材或線捆匯出',title:'線材管理',suffix:'_庫存',name:'線材名稱',newType:'新增線材',newReel:'新增線捆',number:'線捆編號',color:'顏色',status:'補貨狀態',enough:'足量',low:'需補貨',photo:'照片',photoRequired:'請上傳裁線後照片',photoHint:'每次裁線必須上傳照片；超過 2 MB 會自動壓縮。',replacePhoto:'更換照片',viewPhoto:'查看原圖',emptyPhoto:'尚無照片',newCut:'新增裁線紀錄',length:'每條長度（cm）',quantity:'條數',total:'總長度（cm）',actor:'人員',time:'時間',history:'文字紀錄',ledger:'線材紀錄總覽',search:'搜尋線材、編號、顏色、人員',all:'全部',from:'開始日期',to:'結束日期',edit:'修改',delete:'刪除',save:'儲存',cancel:'取消',close:'關閉',back:'返回線材',empty:'尚無紀錄',textSettings:'修改本區文字',open:'開啟線材管理',exportOne:'匯出本項紀錄與照片',exportAll:'匯出整區紀錄與照片',exportTable:'匯出目前表格',previous:'前移',next:'後移',up:'上移',down:'下移',drag:'拖曳排序',processing:'處理中…',duplicate:'名稱或編號已存在',deletePrompt:'確定刪除？有照片或裁線紀錄的線捆會保留，不能刪除。',saved:'已儲存',readonly:'目前沒有編輯權限',required:'請完整填寫資料',updated:'修改時間',createAction:'新增',editAction:'修改',photoAction:'更換照片',statusAction:'調整補貨狀態',sortAction:'調整順序',deleteAction:'刪除',uploadFail:'照片上傳失敗，請重試',saveFail:'尚未儲存，請處理頁面上方提示'};
function wt(k){return state.wireText?.[k]??wireWords[k]??k;}
function we(k){return esc(wt(k));}
function wireTypes(){return state.wireTypes||[];}
function wireReels(typeId){return (state.wireReels||[]).filter(r=>!typeId||r.wireId===typeId);}
function wireCuts(reelId){return (state.wireCuts||[]).filter(c=>!reelId||c.reelId===reelId).sort((a,b)=>b.time.localeCompare(a.time)||b.id.localeCompare(a.id));}
function wireType(id){return wireTypes().find(x=>x.id===id);}
function wireReel(id){return wireReels().find(x=>x.id===id);}
function wirePhotoUrl(r,id,exp=false){return '/api/wire-photos?reel='+encodeURIComponent(r.id)+(id?'&id='+encodeURIComponent(id):'')+(exp?'&export=1':'');}
function wireCanEditCut(c){return currentUser.role==='supervisor'||(canDo('wire.editOwn')&&c.actorId===String(currentUser.id));}
function wireModal(title,body,submit,handler){modal(esc(title),body,submit?wt(submit):'',handler);$('#dialog-form').dataset.processingLabel=wt('processing');$('#cancel-modal').textContent=wt(submit?'cancel':'close');$('#close-modal').setAttribute('aria-label',wt('close'));}
function wireHistory(id){const logs=(state.logs||[]).filter(l=>l.project==='wire:'+id);return '<details class="wire-history"><summary>'+we('history')+'（'+logs.length+'）</summary>'+logs.map(l=>'<div>'+esc(receiptTime(l.time))+'｜'+esc(l.actor)+'｜'+esc(l.action)+(l.detail?'｜'+esc(l.detail):'')+'</div>').join('')+'</details>';}
async function wireCommit(next,action,typeId,detail){if(cloudBusy||failedCandidate)throw Error(wt('saveFail'));state=next;addAudit(action,detail,wt('title')+' > '+(wireType(typeId)?.name||''),'wire:'+typeId);await saveCloud(state);if(failedCandidate)throw Error(wt('saveFail'));if(location.hash==='#admin')renderAdmin();else render();}
function wireActions(){return '<div class="wire-tools"><input id="wire-search" placeholder="'+we('search')+'" aria-label="'+we('search')+'">'+(canDo('wire.create')?'<button type="button" class="primary" id="wire-new">＋ '+we('newType')+'</button>':'')+'<button type="button" id="wire-ledger">'+we('ledger')+'</button>'+(currentUser.role==='supervisor'?'<button type="button" id="wire-export">'+we('exportAll')+'</button>':'')+'</div>';}
function renderWire(){
 const panel=document.createElement('section');panel.className='workspace wire-workspace';panel.innerHTML='<div class="wire-head"><h2>'+we('title')+'</h2>'+wireActions()+'</div><div class="plating-grid" id="wire-grid"></div>';$('main').append(panel);
 function draw(q=''){
 const grid=$('#wire-grid'),visible=wireTypes().filter(t=>t.name.toLowerCase().includes(q.toLowerCase()));
 grid.innerHTML=visible.map(t=>'<div class="plating-tile" data-wire-tile="'+esc(t.id)+'"><button type="button" class="plating-open" data-wire-open="'+esc(t.id)+'">'+esc(t.name)+we('suffix')+'</button>'+(canDo('wire.edit')?'<div class="plating-order">'+[['up','↑'],['down','↓'],['previous','←'],['next','→']].map(([key,symbol])=>'<button type="button" class="small" data-wire-move="'+esc(t.id)+'" data-direction="'+key+'" aria-label="'+we(key)+'" title="'+we(key)+'">'+symbol+'</button>').join('')+'<span class="plating-grip" draggable="true" title="'+we('drag')+'" aria-label="'+we('drag')+'">⠿</span></div>':'')+'</div>').join('')||'<p>'+we('empty')+'</p>';
 const ids=visible.map(t=>t.id),step=direction=>({up:-wireGridColumns(grid),down:wireGridColumns(grid),previous:-1,next:1})[direction];
 grid.updateWireControls=()=>grid.querySelectorAll('[data-wire-move]').forEach(b=>{const to=ids.indexOf(b.dataset.wireMove)+step(b.dataset.direction);b.disabled=to<0||to>=ids.length;});grid.updateWireControls();
 grid.querySelectorAll('[data-wire-open]').forEach(b=>b.onclick=()=>openWire(b.dataset.wireOpen));
 grid.querySelectorAll('[data-wire-move]').forEach(b=>b.onclick=()=>{const target=ids[ids.indexOf(b.dataset.wireMove)+step(b.dataset.direction)];return moveWireTile(b.dataset.wireMove,target,ids,false,q);});
 if(canDo('wire.edit'))grid.querySelectorAll('[data-wire-tile]').forEach(tile=>{const grip=tile.querySelector('.plating-grip');grip.ondragstart=e=>{e.dataTransfer.setData('text/plain',tile.dataset.wireTile);e.dataTransfer.effectAllowed='move';};tile.ondragover=e=>{e.preventDefault();e.dataTransfer.dropEffect='move';};tile.ondrop=e=>{e.preventDefault();return moveWireTile(e.dataTransfer.getData('text/plain'),tile.dataset.wireTile,ids,true,q);};});
 }
 $('#wire-search').oninput=e=>draw(e.target.value);$('#wire-new')?.addEventListener('click',()=>editWireType());$('#wire-ledger').onclick=()=>openWireLedger();$('#wire-export')?.addEventListener('click',()=>exportWire());draw();
}
function wireGridColumns(grid){const columns=getComputedStyle(grid).gridTemplateColumns.trim();const repeat=columns.match(/^repeat\((\d+),/);if(repeat)return Number(repeat[1]);if(columns&&columns!=='none')return columns.split(/\s+/).length;return window.innerWidth<=350?1:window.innerWidth<=650?2:window.innerWidth<=1000?3:4;}
window.addEventListener('resize',()=>$('#wire-grid')?.updateWireControls?.());
async function moveWireTile(id,target,visibleIds,insert=false,search=''){
 if(!canDo('wire.edit')||cloudBusy||failedCandidate||!target||id===target)return;
 const ids=[...visibleIds],from=ids.indexOf(id),to=ids.indexOf(target);if(from<0||to<0)return;
 if(insert)ids.splice(to,0,ids.splice(from,1)[0]);else [ids[from],ids[to]]=[ids[to],ids[from]];
 const next=structuredClone(state),items=new Map(next.wireTypes.map(t=>[t.id,t]));let at=0;
 next.wireTypes=next.wireTypes.map(t=>visibleIds.includes(t.id)?items.get(ids[at++]):t);
 try{await wireCommit(next,wt('sortAction'),id,'第 '+(from+1)+' 位 → 第 '+(to+1)+' 位');const input=$('#wire-search');if(input){input.value=search;input.dispatchEvent(new Event('input'));}}catch(e){toast(e.message);}
}
const renderBeforeWire=render;render=function(){renderBeforeWire();if(activeManagementPage().id==='wire')renderWire();};
function editWireType(id){const old=wireType(id);if(!canDo(old?'wire.edit':'wire.create'))return;wireModal(wt(old?'edit':'newType'),field(we('name'),'name',old?.name||'','required maxlength="100"'),'save',async fd=>{const name=String(fd.get('name')||'').trim();if(!name)throw Error(wt('required'));if(wireTypes().some(t=>t.id!==id&&t.name.toLowerCase()===name.toLowerCase()))throw Error(wt('duplicate'));if(old?.name===name){openWire(id);return;}const next=structuredClone(state),item=old?next.wireTypes.find(t=>t.id===id):{id:crypto.randomUUID(),name};if(old)item.name=name;else{next.wireTypes??=[];next.wireTypes.push(item);}await wireCommit(next,wt(old?'editAction':'createAction'),item.id,old?old.name+' → '+name:name);openWire(item.id);});}
function openWire(id){
 const t=wireType(id);if(!t)return;const reels=wireReels(id);
 wireModal(t.name+wt('suffix'),'<div class="wire-tools">'+(canDo('wire.edit')?'<button type="button" id="wire-rename">'+we('edit')+'</button><button type="button" id="wire-reel-sort">'+we('sortSettings')+'</button>':'')+(canDo('wire.create')?'<button type="button" id="wire-reel-new">＋ '+we('newReel')+'</button>':'')+'<button type="button" id="wire-type-ledger">'+we('ledger')+'</button>'+(currentUser.role==='supervisor'?'<button type="button" id="wire-one-export">'+we('exportOne')+'</button>':'')+(canDo('wire.delete')&&!reels.length?'<button type="button" class="danger-button" id="wire-type-delete">'+we('delete')+'</button>':'')+'</div><div class="ledger-scroll"><table class="ledger-table wire-table"><thead><tr>'+['number','color','status','photo','edit'].map(k=>'<th>'+we(k)+'</th>').join('')+'</tr></thead><tbody>'+reels.map(r=>{const p=r.photos.at(-1);return '<tr><td><button type="button" data-reel-open="'+esc(r.id)+'">'+esc(r.number)+'</button></td><td>'+esc(r.color)+'</td><td>'+(['warehouse','supervisor'].includes(currentUser.role)?'<select class="wire-status '+r.status+'" data-reel-status="'+esc(r.id)+'" aria-label="'+we('status')+'">'+['enough','low'].map(s=>'<option value="'+s+'" '+(s===r.status?'selected':'')+'>'+we(s)+'</option>').join('')+'</select>':'<span class="wire-status '+r.status+'">'+we(r.status)+'</span>')+'</td><td><button type="button" class="wire-thumb" data-reel-photo="'+esc(r.id)+'" aria-label="'+we(canDo('wire.photos')?'replacePhoto':'viewPhoto')+'">'+(p?'<img loading="lazy" src="'+esc(wirePhotoUrl(r,p.id))+'" alt="'+esc(r.number)+' '+we('photo')+'">':we('emptyPhoto'))+'</button></td><td>'+(canDo('wire.edit')?'<button type="button" class="small" data-reel-edit="'+esc(r.id)+'">'+we('edit')+'</button>':'')+(canDo('wire.delete')&&!r.photos.length&&!wireCuts(r.id).length?'<button type="button" class="small danger-button" data-reel-delete="'+esc(r.id)+'">'+we('delete')+'</button>':'')+'</td></tr>';}).join('')+'</tbody></table></div>'+(!reels.length?'<p>'+we('empty')+'</p>':'')+wireHistory(id));
 $('#wire-reel-sort')?.addEventListener('click',()=>sortWireReels(id));$('#wire-rename')?.addEventListener('click',()=>editWireType(id));$('#wire-reel-new')?.addEventListener('click',()=>editWireReel(id));$('#wire-type-ledger').onclick=()=>openWireLedger(id);$('#wire-one-export')?.addEventListener('click',()=>exportWire(id));$('#wire-type-delete')?.addEventListener('click',async()=>{if(!await confirmAction(wt('deletePrompt')))return;try{const next=structuredClone(state);next.wireTypes=next.wireTypes.filter(x=>x.id!==id);await wireCommit(next,wt('deleteAction'),id,t.name);$('#modal').close();}catch(e){toast(e.message);}});
 document.querySelectorAll('[data-reel-open]').forEach(b=>b.onclick=()=>openWireReel(b.dataset.reelOpen));document.querySelectorAll('[data-reel-edit]').forEach(b=>b.onclick=()=>editWireReel(id,b.dataset.reelEdit));document.querySelectorAll('[data-reel-photo]').forEach(b=>b.onclick=()=>wirePhotoDialog(b.dataset.reelPhoto));
 document.querySelectorAll('[data-reel-delete]').forEach(b=>b.onclick=()=>deleteWireReel(b.dataset.reelDelete));
 document.querySelectorAll('[data-reel-status]').forEach(select=>select.onchange=async()=>{select.disabled=true;const old=wireReel(select.dataset.reelStatus),value=select.value;if(old.status===value)return;try{const next=structuredClone(state);next.wireReels.find(r=>r.id===old.id).status=value;await wireCommit(next,wt('statusAction'),id,old.number+'：'+wt(old.status)+' → '+wt(value));openWire(id);}catch(e){select.value=old.status;toast(e.message);}finally{select.disabled=false;}});
}
function nextWireReelNumber(typeId){const values=wireReels(typeId).map(r=>Number(r.number)).filter(n=>Number.isSafeInteger(n)&&n>0);return String(Math.max(0,...values)+1);}
function sortWireReels(typeId){if(!canDo('wire.edit'))return;const reels=wireReels(typeId);numberedOrderDialog(wt('sortSettings'),reels.map(r=>({id:r.id,label:r.number+'｜'+r.color})),async ids=>{const next=structuredClone(state),map=new Map(next.wireReels.map(r=>[r.id,r]));let i=0;next.wireReels=next.wireReels.map(r=>r.wireId===typeId?map.get(ids[i++]):r);await wireCommit(next,wt('sortAction'),typeId,ids.map(id=>map.get(id).number).join(' → '));},()=>openWire(typeId));}
function editWireReel(typeId,id){const old=wireReel(id);if(!canDo(old?'wire.edit':'wire.create'))return;
 wireModal(wt(old?'edit':'newReel'),'<div class="form-grid">'+field(we('number'),'number',old?.number||nextWireReelNumber(typeId),'required maxlength="100"'+(!old?' readonly':'' ))+field(we('color'),'color',old?.color||'','required maxlength="100"')+'</div>'+(old&&canDo('wire.delete')&&!old.photos.length&&!wireCuts(id).length?'<button type="button" class="danger-button" id="reel-delete">'+we('delete')+'</button>':''),'save',async fd=>{const number=String(fd.get('number')||'').trim(),color=String(fd.get('color')||'').trim();if(!number||!color)throw Error(wt('required'));if(wireReels(typeId).some(r=>r.id!==id&&r.number===number))throw Error(wt('duplicate'));const next=structuredClone(state),r=old?next.wireReels.find(r=>r.id===id):{id:crypto.randomUUID(),wireId:typeId,photos:[],status:'enough'};const changes=[];for(const [k,v]of [['number',number],['color',color]]){if(old&&old[k]!==v)changes.push(wt(k)+'：'+old[k]+' → '+v);r[k]=v;}if(old&&!changes.length){openWire(typeId);return;}if(!old){next.wireReels??=[];next.wireReels.push(r);}await wireCommit(next,wt(old?'editAction':'createAction'),typeId,old?changes.join('；'):number+'｜'+color);openWire(typeId);});
 $('#reel-delete')?.addEventListener('click',async()=>{if(!await confirmAction(wt('deletePrompt')))return;try{const next=structuredClone(state);next.wireReels=next.wireReels.filter(r=>r.id!==id);await wireCommit(next,wt('deleteAction'),typeId,old.number);openWire(typeId);}catch(e){toast(e.message);}});
}
async function deleteWireReel(id){const old=wireReel(id);if(!old||!canDo('wire.delete')||!await confirmAction(wt('deletePrompt')))return;try{const next=structuredClone(state);next.wireReels=next.wireReels.filter(r=>r.id!==id);await wireCommit(next,wt('deleteAction'),old.wireId,old.number);openWire(old.wireId);}catch(e){toast(e.message);}}
function wireCutRows(cuts){return cuts.map(c=>{const r=wireReel(c.reelId),t=wireType(r?.wireId);return {c,r,t};}).filter(x=>x.r&&x.t);}
function wireCutTable(rows,withType=true){return '<div class="ledger-scroll"><table class="ledger-table wire-table"><thead><tr>'+['time',...(withType?['name','number','color']:[]),'actor','length','quantity','photo','edit'].map(k=>'<th>'+we(k)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(({c,r,t})=>'<tr><td>'+esc(receiptTime(c.time))+'</td>'+(withType?'<td>'+esc(t.name)+'</td><td>'+esc(r.number)+'</td><td>'+esc(r.color)+'</td>':'')+'<td>'+esc(c.actor)+'</td><td>'+c.length+'</td><td>'+c.quantity+'</td><td><a class="wire-thumb" href="'+esc(wirePhotoUrl(r,c.photoId))+'" target="_blank" rel="noopener"><img loading="lazy" src="'+esc(wirePhotoUrl(r,c.photoId))+'" alt="'+we('photo')+'"></a></td><td>'+(wireCanEditCut(c)?'<button type="button" class="small" data-cut-edit="'+esc(c.id)+'">'+we('edit')+'</button>':'')+'</td></tr>').join('')+'</tbody></table></div>'+(!rows.length?'<p>'+we('empty')+'</p>':'');}
function bindCutEdits(){document.querySelectorAll('[data-cut-edit]').forEach(b=>b.onclick=()=>{const c=(state.wireCuts||[]).find(x=>x.id===b.dataset.cutEdit);editWireCut(c.reelId,c.id);});}
function openWireReel(id){const r=wireReel(id),t=wireType(r?.wireId);if(!r||!t)return;
 wireModal(t.name+'｜'+r.number+'｜'+r.color,'<div class="wire-tools"><button type="button" id="wire-back">← '+we('back')+'</button>'+(canDo('wire.cut')&&canDo('wire.photos')?'<button type="button" class="primary" id="wire-cut-new">＋ '+we('newCut')+'</button>':'')+(currentUser.role==='supervisor'?'<button type="button" id="wire-reel-export">'+we('exportOne')+'</button>':'')+'</div>'+wireCutTable(wireCutRows(wireCuts(id)),false));$('#wire-back').onclick=()=>openWire(t.id);$('#wire-cut-new')?.addEventListener('click',()=>editWireCut(id));$('#wire-reel-export')?.addEventListener('click',()=>exportWire(t.id,id));bindCutEdits();
}
function wirePhotoField(required){return '<label class="field">'+we('photo')+'<input type="file" id="wire-photo-file" name="photo" accept="image/jpeg,image/png,image/webp" '+(required?'required':'')+'></label><small>'+we('photoHint')+'</small>';}
