function wireCsvRows(rows){return [[wt('time'),wt('name'),wt('number'),wt('color'),wt('actor'),wt('length'),wt('quantity'),wt('total'),wt('updated'),wt('modifiedBy'),'照片編號'],...rows.map(({c,r,t})=>[receiptTime(c.time),t.name,r.number,r.color,c.actor,c.length,c.quantity,Math.round(c.length*c.quantity*100)/100,c.updatedAt?receiptTime(c.updatedAt):'',c.updatedBy||'',c.photoId])];}
function openWireLedger(typeId=''){
 const rows=wireCutRows(wireCuts());wireModal(wt('ledger'),'<div class="wire-tools"><input id="wire-ledger-query" placeholder="'+we('search')+'"><select id="wire-ledger-type"><option value="">'+we('all')+'</option>'+wireTypes().map(t=>'<option value="'+esc(t.id)+'" '+(t.id===typeId?'selected':'')+'>'+esc(t.name)+'</option>').join('')+'</select><label>'+we('from')+'<input type="date" id="wire-ledger-from"></label><label>'+we('to')+'<input type="date" id="wire-ledger-to"></label>'+(currentUser.role==='supervisor'?'<button type="button" id="wire-ledger-export">'+we('exportTable')+'</button>':'')+'</div><div id="wire-ledger-table"></div>');let shown=[];
 function draw(){const q=$('#wire-ledger-query').value.trim().toLowerCase(),type=$('#wire-ledger-type').value,from=$('#wire-ledger-from').value,to=$('#wire-ledger-to').value;shown=rows.filter(x=>{const d=new Date(x.c.time).toLocaleDateString('sv-SE');return(!type||x.t.id===type)&&(!from||d>=from)&&(!to||d<=to)&&[x.t.name,x.r.number,x.r.color,x.c.actor].join(' ').toLowerCase().includes(q);});$('#wire-ledger-table').innerHTML=wireCutTable(shown);bindCutEdits();}
 for(const id of ['query','type','from','to'])$('#wire-ledger-'+id).oninput=draw;$('#wire-ledger-export')?.addEventListener('click',async()=>{if(!await authorizeExport())return;await downloadBlob(new Blob([platingCsv(wireCsvRows(shown))],{type:'text/csv;charset=utf-8'}),wt('ledger')+'.csv');});draw();
}
let wireExportBusy=false;
async function exportWire(typeId='',reelId=''){
 if(wireExportBusy)return;wireExportBusy=true;if(!await authorizeExport()){wireExportBusy=false;return;}const snapshot=structuredClone(state),types=(snapshot.wireTypes||[]).filter(t=>!typeId||t.id===typeId),reels=(snapshot.wireReels||[]).filter(r=>types.some(t=>t.id===r.wireId)&&(!reelId||r.id===reelId)),cuts=(snapshot.wireCuts||[]).filter(c=>reels.some(r=>r.id===c.reelId)).sort((a,b)=>b.time.localeCompare(a.time));const entries=[],manifest=[['線材','線捆','上傳人員','上傳時間','原始檔名','ZIP位置']];let bytes=0;
 try{for(const [ri,r]of reels.entries()){const t=types.find(t=>t.id===r.wireId);for(const [pi,p]of r.photos.entries()){const res=await apiFetch(wirePhotoUrl(r,p.id,true));if(!res.ok)throw Error(wt('uploadFail'));const data=new Uint8Array(await res.arrayBuffer());bytes+=data.length;if(bytes>250*1024*1024)throw Error(wt('exportTooLarge'));const ext=(res.headers.get('content-type')||'').includes('png')?'png':(res.headers.get('content-type')||'').includes('webp')?'webp':'jpg',path=String(types.indexOf(t)+1).padStart(3,'0')+'_'+safeFileName(t.name)+'/'+String(ri+1).padStart(3,'0')+'_'+safeFileName(r.number)+'_'+safeFileName(r.color)+'/'+String(pi+1).padStart(3,'0')+'_'+photoStamp(p.created)+'.'+ext;entries.push({name:path,data,date:p.created});manifest.push([t.name,r.number,p.actor,receiptTime(p.created),p.name,path]);}}
 const rows=cuts.map(c=>{const r=reels.find(r=>r.id===c.reelId);return {c,r,t:types.find(t=>t.id===r.wireId)};});entries.push({name:'裁線紀錄.csv',data:platingCsv(wireCsvRows(rows))},{name:'線捆庫存.csv',data:platingCsv([[wt('name'),wt('number'),wt('color'),wt('status')],...reels.map(r=>[types.find(t=>t.id===r.wireId).name,r.number,r.color,wt(r.status)])])},{name:'照片清單.csv',data:platingCsv(manifest)},{name:'文字紀錄.csv',data:platingCsv([['時間','人員','動作','內容'],...(snapshot.logs||[]).filter(l=>types.some(t=>l.project==='wire:'+t.id)).map(l=>[receiptTime(l.time),l.actor,l.action,l.detail])])});await downloadBlob(makeZip(entries),'線材紀錄_'+photoStamp(new Date())+'.zip');
 }catch(e){toast(e.message);}finally{wireExportBusy=false;}
}
const renderAdminBeforeWire=renderAdmin;renderAdmin=function(){renderAdminBeforeWire();if(currentUser.role!=='supervisor')return;const card=document.createElement('details');card.id='wire-admin';card.className='admin-card';card.innerHTML='<summary><h2>'+we('title')+'</h2></summary><div class="admin-card-body"><div class="wire-tools"><button type="button" id="wire-text">'+we('textSettings')+'</button><button type="button" id="wire-admin-new">＋ '+we('newType')+'</button><a class="admin-back-button" href="#wire">'+we('open')+'</a></div>'+wireTypes().map(t=>'<div class="admin-row"><strong>'+esc(t.name)+we('suffix')+'</strong><button type="button" data-wire-admin-open="'+esc(t.id)+'">'+we('edit')+'</button></div>').join('')+'</div>';$('main').append(card);$('#wire-admin-new').onclick=()=>editWireType();card.querySelectorAll('[data-wire-admin-open]').forEach(b=>b.onclick=()=>openWire(b.dataset.wireAdminOpen));$('#wire-text').onclick=()=>wireModal(wt('textSettings'),Object.keys(wireWords).map(k=>field(esc(wireWords[k]),k,wt(k),'required maxlength="100"')).join(''),'save',async fd=>{const next=structuredClone(state);next.wireText=Object.fromEntries(Object.keys(wireWords).map(k=>[k,String(fd.get(k)||'').trim()]));if(Object.values(next.wireText).some(v=>!v))throw Error(wt('required'));if(stableJSON(next.wireText)===stableJSON(state.wireText)){$('#modal').close();return;}await wireCommit(next,wt('editAction')+' '+wt('textSettings'),'','');$('#modal').close();renderAdmin();});};
